@import url("css/dropkick.css");
@import url("../_common/_plugin/froala_editor/2.7.1/css/froala_style.min.css");
* { text-decoration: none; list-style-type: none; margin: 0px; padding: 0px; }
noscript, caption { text-indent: -20000px; height: 0px; width: 0px; }
.jw_skip { position: absolute; left: -5000px; }
div, ul, li, a, input, select, form, dl, dt, dd { list-style-type: none; }
fieldset, img { border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }
img, input, select, textarea { vertical-align: middle; }
img { border: 0px; }
s, strike, del { text-decoration: line-through !important; }
u, ins { text-decoration: underline !important; }
.jwxe_board table.vmode td ul, .jwxe_board table.vmode td ol, .jwxe_board table.vmode td dl { padding-left: 20px; padding-right: 20px; }
h1, h2, h3, h4, h5, h6 { font-weight: bolder; }
a:link, a:visited, a:hover { text-decoration: none; }
.jwxe_canvas { display: block; position: relative; background-color: rgb(246, 246, 246); }
.jwxe_root { display: block; position: relative; top: 0px; left: 0px; }
.jwxe_survey { display: block; position: relative; top: 0px; left: 0px; }
.jwxe_alt { position: absolute; left: -5000px; }
