.jwxe_movie { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_div { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_h { display: block; position: absolute; top: 0px; left: 0px; font-weight: bolder; }
.jwxe_session_container { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_item_include { display: block; position: absolute; top: 0px; left: 0px; }
