.jwxe_mnu_template { display: inline-block; position: absolute; top: 0px; left: 0px; }
.jwxe_navigator { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_text { display: block; position: absolute; top: 0px; left: 0px; padding: 0px 0px 0px 1px; }
.jwxe_a, .jwxe_a_master { display: inline-block; position: absolute; text-decoration: none; top: 0px; left: 0px; }
.jwxe_right_scroll_anchor { display: inline-block; position: absolute; text-decoration: none; top: 0px; left: 0px; }
.jwxe_a_zoom_in, .jwxe_a_zoom_out, .jwxe_a_zoom_cancel, .jwxe_a_pdf, .jwxe_a_print { cursor: pointer; display: inline-block; position: absolute; text-decoration: none; top: 0px; left: 0px; }
.jw_selected { font-weight: bold; }
.jwxe_img { display: inline-block; position: absolute; top: 0px; left: 0px; }
.jwxe_input_text { border: 1px solid rgb(210, 210, 210); display: inline-block; position: absolute; top: 0px; left: 0px; font-size: 12px; }
.jwxe_select { border: 1px solid rgb(210, 210, 210); display: inline-block; position: absolute; top: 0px; left: 0px; font-size: 12px; }
.jwxe_ul { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_span { display: inline-block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_ptag { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_html { display: block; position: absolute; line-height: 18px; top: 0px; left: 0px; }
.jwxe_iframe { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_map { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_label { display: inline-block; position: absolute; top: 0px; left: 0px; }
.jwxe_label span { margin: 5px; display: block; }
.jwxe_include_item, .jwxe_import { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_include_banner { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_include_sync_menu { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_include_popupzone { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_popupzone { display: block; position: relative; top: 0px; left: 0px; }
.popup_guide { display: block; position: absolute; z-index: 110 !important; }
.popup-wrap { display: block; position: absolute; top: 0px; left: 0px; width: 100%; height: 100%; overflow: hidden; }
.jwxe_qrcode { display: inline-block; position: absolute; top: 0px; left: 0px; }
.jwxe_qrcode iframe { border: 0px; overflow: hidden; padding: 0px; }
.jwxe_form { display: block; position: absolute; top: 0px; left: 0px; }
.jwxe_input_submit { border-width: medium; border-style: none; border-color: currentcolor; border-image: none; display: inline-block; position: absolute; top: 0px; left: 0px; cursor: pointer; }
.jwxe_address { position: absolute; top: 0px; left: 0px; }
.jwxe_menu_box0 { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_main_hidden_menu { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_menu_box1 { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_menu_box2 { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_quick_menu { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_quick_side_menu { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_quick_right_side_menu { display: block; position: absolute; list-style-type: none; top: 0px; left: 0px; }
.jwxe_banner { display: block; position: absolute; list-style-type: none; overflow: hidden; top: 0px; left: 0px; }
.jwxe_banner1 { display: block; position: absolute; list-style-type: none; overflow: hidden; top: 0px; left: 0px; z-index: 1; }
