.jwxe_banner2 { display: block; position: absolute; list-style-type: none; overflow: hidden; top: 0px; left: 0px; }
.jwxe_popup { visibility: hidden; position: absolute; background-color: rgb(255, 255, 255); top: 0px; left: 0px; box-shadow: rgba(0, 0, 0, 0.2) 8px 11px 8px 0px, rgba(0, 0, 0, 0.19) 0px 13px 20px 0px; }
.popup-window .jwxe_popup { box-shadow: none; }
.jwxe_popup.ui-draggable { cursor: move; }
.jwxe_popup_close { display: block; position: absolute; left: 0px; top: 0px; width: 49px; height: 19px; background: url("./img/popup_close.gif") no-repeat transparent; }
.jwxe_popup_close_1 { display: block; position: absolute; left: 0px; top: 0px; width: 109px; height: 19px; background: url("./img/popup_close_1.gif") no-repeat transparent; }
.jwxe_popup_close_7 { display: block; position: absolute; left: 0px; top: 0px; width: 109px; height: 19px; background: url("./img/popup_close_7.gif") no-repeat transparent; }
.jwxe_survey_q { position: relative; margin-bottom: 5px; }
.jwxe_survey_r { position: relative; margin-bottom: 5px; }
.jwxe_survey_vote { display: block; position: absolute; left: 0px; top: 0px; width: 73px; height: 19px; }
.jwxe_survey_result { display: block; position: absolute; left: 0px; top: 0px; width: 73px; height: 19px; }
@media (max-width: 480px) {
  .jwxe_popup { position: relative; box-shadow: none; left: auto !important; top: auto !important; width: 100% !important; }
}
.owl-carousel { touch-action: manipulation; }
.jwxe_ul > li, .jwxe_menu_box0 > li, .jwxe_menu_box1 > li, .jwxe_menu_box2 > li, .jwxe_banner > li, .jwxe_banner1 > li, .jwxe_banner2 > li, .jwxe_quick_menu > li, .jwxe_quick_side_menu > li, .jwxe_tab_swipe > li { display: inline; }
