#go_main { position: absolute; height: 0px; }
#go_main a { display: block; left: -2000px; position: absolute; text-align: center; width: 400px; }
#go_main a:focus, #go_main a:active, #go_main a:hover { background-color: rgb(255, 255, 255); color: black; left: 50%; padding: 5px 0px; position: absolute; top: 10px; z-index: 1000000; border: 1px dotted red; }
.ui-datepicker { background-color: rgb(255, 255, 255); border: 1px solid rgb(209, 218, 234); padding: 5px; z-index: 100000; }
.ui-datepicker td span, .ui-datepicker td a { display: block; padding: 0.2em; text-align: right; text-decoration: none; }
.jw_selected + ul.jw-dsp-none { display: block; }
.none { display: none; }
.jwxe_stline { position: static; display: inline; }
.jwxe_stblock { position: static; display: block; }
.jwxe_relative { position: relative; }
.jw-relative { position: relative; }
.jw-static { position: static; display: inline; }
li.jwxe_li.jw-relative { position: relative; }
.jw-fl-left { float: left; }
.jw-fl-right { float: right; }
.jw-fl-none { float: none; }
.jw-cl-left { clear: left; }
.jw-cl-right { clear: right; }
.jw-cl-both { clear: both; }
.jw-dsp-none, li.jwxe_li.jw-dsp-none { display: none; }
.jw-txt-left { text-align: left; }
.jw-txt-right { text-align: right; }
.jw-txt-center { text-align: center; }
a.sbtn { background: url("img/btn_app.gif") left 0px repeat scroll transparent; color: rgb(102, 102, 102); cursor: pointer; display: block; float: left; font-size: 11px; font-weight: normal; height: 21px; letter-spacing: -1px; margin-right: 3px; overflow: hidden; padding-left: 6px; text-decoration: none; }
a.sbtn.hover { background: url("img/btn_app.gif") left -21px repeat scroll transparent; }
a.sbtn span { background: url("img/btn_app.gif") right 0px repeat scroll transparent; display: block; float: left; height: 21px; line-height: 210%; overflow: hidden; padding-right: 6px; color: rgb(102, 102, 102); }
a.sbtn.hover span { background: url("img/btn_app.gif") right -21px repeat scroll transparent; color: rgb(0, 0, 0); }
a.sbtn:hover span { color: rgb(0, 0, 0); }
.flash-map { display: inline-block; text-indent: -99999px; position: absolute; width: 0px; height: 0px; }
.jw-edit-btn { font-size: 14px; padding: 5px 10px; border-radius: 6px; background-color: white; display: inline-block; border: 2px solid rgb(170, 170, 170); margin-right: 10px; }
div.cms-edit.cms-editing { position: relative !important; cursor: pointer; }
div.cms-edit.cms-editing a.cms-edit-btn, div.cms-edit.cms-editing a.cms-edit-img { width: auto !important; height: auto !important; min-width: auto !important; min-height: auto !important; }
.CodeMirror { height: 100%; }
.CodeMirror pre, .CodeMirror pre * { font-size: 13px !important; }
span.fr-img-caption span.fr-img-wrap img { width: auto !important; }
span.fr-img-caption span.fr-img-wrap img { width: 100% !important; }

.owl-carousel, .owl-carousel .owl-item { -webkit-tap-highlight-color: transparent; position: relative; }
.owl-carousel { display: none; width: 100%; z-index: 1; }
.owl-carousel .owl-stage { position: relative; }
.owl-carousel .owl-stage::after { content: "."; display: block; clear: both; visibility: hidden; line-height: 0; height: 0px; }
.owl-carousel .owl-stage-outer { position: relative; overflow: hidden; transform: translate3d(0px, 0px, 0px); }
.owl-carousel .owl-item, .owl-carousel .owl-wrapper { backface-visibility: hidden; transform: translate3d(0px, 0px, 0px); }
.owl-carousel .owl-item { min-height: 1px; float: left; backface-visibility: hidden; }
.owl-carousel .owl-item img { display: block; width: 100%; }
.owl-carousel .owl-dots.disabled, .owl-carousel .owl-nav.disabled { display: none; }
.no-js .owl-carousel, .owl-carousel.owl-loaded { display: block; }
.owl-carousel .owl-dot, .owl-carousel .owl-nav .owl-next, .owl-carousel .owl-nav .owl-prev { cursor: pointer; user-select: none; }
.owl-carousel.owl-loading { opacity: 0; display: block; }
.owl-carousel.owl-hidden { opacity: 0; }
.owl-carousel.owl-refresh .owl-item { visibility: hidden; }
.owl-carousel.owl-drag .owl-item { user-select: none; }
.owl-carousel.owl-grab { cursor: grab; }
.owl-carousel.owl-rtl { direction: rtl; }
.owl-carousel.owl-rtl .owl-item { float: right; }
.owl-carousel .animated { animation-duration: 1s; animation-fill-mode: both; }
.owl-carousel .owl-animated-in { z-index: 0; }
.owl-carousel .owl-animated-out { z-index: 1; }
.owl-carousel .fadeOut { animation-name: fadeOut; }
@keyframes fadeOut { 
  0% { opacity: 1; }
  100% { opacity: 0; }
}
.owl-height { transition: height 0.5s ease-in-out; }
.owl-carousel .owl-item .owl-lazy { opacity: 0; transition: opacity 0.4s; }
.owl-carousel .owl-item img.owl-lazy { transform-style: preserve-3d; }
.owl-carousel .owl-video-wrapper { position: relative; height: 100%; background: rgb(0, 0, 0); }
.owl-carousel .owl-video-play-icon { position: absolute; height: 80px; width: 80px; left: 50%; top: 50%; margin-left: -40px; margin-top: -40px; background: url("owl.video.play.png") no-repeat; cursor: pointer; z-index: 1; backface-visibility: hidden; transition: transform 0.1s; }
.owl-carousel .owl-video-play-icon:hover { transform: scale(1.3, 1.3); }
.owl-carousel .owl-video-playing .owl-video-play-icon, .owl-carousel .owl-video-playing .owl-video-tn { display: none; }
.owl-carousel .owl-video-tn { opacity: 0; height: 100%; background-position: center center; background-repeat: no-repeat; background-size: contain; transition: opacity 0.4s; }
.owl-carousel .owl-video-frame { position: relative; z-index: 1; height: 100%; width: 100%; }
.owl-theme .owl-dots, .owl-theme .owl-nav { text-align: center; -webkit-tap-highlight-color: transparent; }
.owl-theme .owl-nav { margin-top: 10px; }
.owl-theme .owl-nav [class*="owl-"] { color: rgb(255, 255, 255); font-size: 14px; margin: 5px; padding: 4px 7px; background: rgb(214, 214, 214); display: inline-block; cursor: pointer; border-radius: 3px; }
.owl-theme .owl-nav [class*="owl-"]:hover { background: rgb(134, 151, 145); color: rgb(255, 255, 255); text-decoration: none; }
.owl-theme .owl-nav .disabled { opacity: 0.5; cursor: default; }
.owl-theme .owl-nav.disabled + .owl-dots { margin-top: 10px; }
.owl-theme .owl-dots .owl-dot { display: inline-block; zoom: 1; }
.owl-theme .owl-dots .owl-dot span { width: 10px; height: 10px; margin: 5px 3px; background: rgb(255, 255, 255); display: block; backface-visibility: visible; transition: opacity 0.2s; border-radius: 30px; }
.owl-theme .owl-dots .owl-dot.active span, .owl-theme .owl-dots .owl-dot:hover span { background: rgb(134, 151, 145); }

.swiper-container { margin-left: auto; margin-right: auto; position: relative; overflow: hidden; list-style: none; padding: 0px; z-index: 1; }
.swiper-container-no-flexbox .swiper-slide { float: left; }
.swiper-container-vertical > .swiper-wrapper { -webkit-box-orient: vertical; -webkit-box-direction: normal; flex-direction: column; }
